const t=k=>dictionary[k]?.[lang==='fa'?1:0]||k,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat(lang==='fa'?'fa-IR':'en-CA',{style:'currency',currency:'CAD'}).format(n),mins=s=>s.split(':').reduce((a,b)=>a*60+Number(b)),clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
function now(d=new Date()){let p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(x=>[x.type,x.value]));return {date:`${p.year}-${p.month}-${p.day}`,minute:+p.hour*60 + +p.minute}}
function addDays(date,n){let d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function codeFor(used){for(let i=0;i<10000;i++){let a=new Uint32Array(1);crypto.getRandomValues(a);if(a[0]>=4294800000)continue;let code=String(100000+a[0]%900000);if(!used.includes(code))return code}throw Error(t('capacityError'))}
function seed(){throw Error('Demo reset is disabled in production');}
let db=window.BAANOU_INITIAL;
let bookingDay=addDays(now().date,1);const states=['pending','confirmed','baking','ready','delivered','cancelled'];
function read(){}function user(){return db.users.find(u=>u.id===userId)}
async function atomic(){throw Error('Server operation required');}
function count(){return cart.reduce((a,b)=>a+b,0)}function total(){return cart.reduce((a,n,i)=>a+n*db.breads[i].price,0)}function duration(q=cart){return Math.max(0,...db.breads.map((b,i)=>q[i]?b.bake:0))}
function usedAt(date,start,end,orders=db.orders){let events=[];for(let o of orders.filter(o=>o.date===date&&o.status!=='cancelled')){let stop=o.start+Math.max(0,...o.items.filter(i=>i.qty).map(i=>i.bake));if(o.start<end&&stop>start){let q=o.items.reduce((a,i)=>a+i.qty,0);events.push([Math.max(start,o.start),q],[Math.min(end,stop),-q])}}events.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);let used=0,max=0;for(let e of events){used+=e[1];max=Math.max(max,used)}return max}
function dayAllowed(date){let s=db.settings,n=now();return date>=n.date&&date<=addDays(n.date,s.horizon)&&s.days.includes(new Date(date+'T12:00:00Z').getUTCDay())&&!s.holidays.includes(date)}
function slots(date,q=cart){let s=db.settings,n=now(),qty=q.reduce((a,b)=>a+b,0),dur=duration(q),out=[];for(let [session,se] of s.sessions.entries())for(let start=mins(se.start);start<mins(se.end);start+=s.interval){let ov=s.overrides[date+'@'+clock(start)]||{},os=db.orders.filter(o=>o.date===date&&o.start===start&&o.status!=='cancelled'),used=os.reduce((a,o)=>a+o.items.reduce((a,i)=>a+i.qty,0),0),left=Math.max(0,Math.min((ov.capacity??s.slotCapacity)-used,s.ovens*s.ovenCapacity-usedAt(date,start,start+Math.max(dur,1)))),valid=dayAllowed(date)&&!(date===n.date&&start<=n.minute)&&!ov.disabled&&(s.overrun||start+dur+s.packing<=mins(se.end))&&os.length<s.maxOrders;out.push({start,session,left,end:start+dur+s.packing,ok:valid&&qty>0&&qty<=left,state:!valid?'unavailable':left===0?'full':left<qty||left<10?'limited':'available'})}return out}
function toast(msg){let e=document.getElementById('toast');e.textContent=msg;e.hidden=false;setTimeout(()=>e.hidden=true,5000)}function go(v){view=v;render();window.scrollTo(0,0)}function toggleLang(){lang=lang==='en'?'fa':'en';BAANOU_STORE.setItem('bano-v2-lang',lang);render()}
function art(i){let marks=Array.from({length:i===1?7:24},(_,j)=>i===1?`<path d="M${65+j*24} 52 Q${55+j*24} 100 ${65+j*24} 151" stroke="#a0652b" stroke-width="6" fill="none"/>`:`<circle cx="${59+(j%6)*39}" cy="${54+Math.floor(j/6)*30}" r="${i===2?5:3}" fill="#9c672d"/>`).join('');return `<svg viewBox="0 0 340 205" aria-hidden="true"><defs><radialGradient id="g${i}"><stop stop-color="#f8dda2"/><stop offset=".7" stop-color="#dfac59"/><stop offset="1" stop-color="#9c5b27"/></radialGradient></defs><path d="${i===1?'M33 105 Q28 35 95 28 L257 34 Q309 41 304 103 Q299 171 239 176 L93 169 Q36 167 33 105':i===2?'M25 146 L65 35 Q174 18 276 44 L312 140 Q253 178 176 168 L73 181 Z':'M26 106 Q30 30 169 25 Q307 29 314 103 Q302 180 168 181 Q30 173 26 106'}" fill="url(#g${i})" stroke="#b67932" stroke-width="3"/>${marks}</svg>`}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.getElementById('brand').innerHTML=(db.settings.logo?`<img src="${E(brandImage(db.settings.logo))}" style="height:30px;max-width:80px" alt=""> `:'')+E(db.settings.name)+'<small>BAKED WITH CARE</small>';document.getElementById('nav').innerHTML=`<button onclick="go('home')">${t('home')}</button><button onclick="go('account')">${t('account')}</button><button onclick="go('admin')">${t('admin')}</button><button onclick="toggleLang()">${lang==='en'?'فارسی':'EN'}</button><button aria-label="${t('bread')}" onclick="go('home')">◌ ${count()}</button>`;document.getElementById('demo').textContent=t('demo');document.getElementById('bar').innerHTML='';let html=view==='home'?home():view==='schedule'?schedule():view==='checkout'?checkoutPage():view==='confirmation'?confirmation():view==='track'?tracking():view==='account'?accountPage():adminPage();document.getElementById('app').innerHTML=html+`<footer>${E(db.settings.name)} · ${E(db.settings.address)} · ${E(db.settings.phone)}<br>${t('local')}<details class="small"><summary style="font-size:13px">${lang==='fa'?'منابع و مجوز عکس‌ها':'Photo credits & licenses'}</summary><p>Traditional: <a href="https://commons.wikimedia.org/wiki/File:Taftan_nan_01.jpg">Taftan nan 01</a>, www.theedinburghblog.co.uk · <a href="https://creativecommons.org/licenses/by/2.0/">CC BY 2.0</a> · crop by Anna Frodesiak. Barbari: <a href="https://commons.wikimedia.org/wiki/File:Iranian_Bread_1.JPG">IDangerMouse</a>, public domain. Sangak: <a href="https://commons.wikimedia.org/wiki/File:Sangak_bread.jpg">Mehrraz</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Images resized/recompressed and displayed with a CSS crop. Font: Inter (Rasmus Andersson), Vazirmatn (Saber Rastikerdar), SIL Open Font License 1.1.</p></details></footer>`}
function progress(n){return `<div class="steps">${['bread','schedule','checkout','confirmation'].map((k,i)=>`<span class="${i+1===n?'active':''}">${i+1} · ${t(k)}</span>`).join('')}</div>`}
function home(){document.getElementById('bar').innerHTML=`<div class="bar row"><div>${count()} ${t('loaves')} · <strong>${money(total())}</strong>${walkin?' · '+t('walkin'):''}</div><button class="primary" ${count()?'':'disabled'} onclick="go('schedule')">${t('continue')} →</button></div>`;return `<section class="hero"><div class="eyebrow">${t('tag')}</div><h1>${t('hero')}</h1><p class="muted">${t('intro')}</p></section><div class="grid">${db.breads.map((b,i)=>`<article class="card"><div class="art">${b.image?`<img src="${E(b.image)}" alt="${E(b[lang])}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div hidden>${art(i)}</div>`:art(i)}</div><div class="pad"><div class="eyebrow">0${i+1} / BANO</div><h3>${E(b[lang])}</h3><p class="muted small">${E(b[lang==='fa'?'descriptionFa':'descriptionEn'])}</p><div class="row"><b>${money(b.price)}</b><div class="qty"><button aria-label="${E(b[lang])} −" ${cart[i]?'':'disabled'} onclick="qty(${i},-1)">−</button><b>${cart[i]}</b><button aria-label="${E(b[lang])} +" ${b.active&&cart[i]<b.max?'':'disabled'} onclick="qty(${i},1)">+</button></div></div>${!b.active?`<span class="badge">${t('unavailable')}</span>`:''}</div></article>`).join('')}</div>`}
function qty(i,n){cart[i]=Math.max(0,Math.min(db.breads[i].max,cart[i]+n));chosen='';render()}
function schedule(){let list=slots(bookingDay),pick=list.find(x=>String(x.start)===chosen);return `${progress(2)}<h2>${t('schedule')}</h2><p class="muted">America/Vancouver · ${now().date} ${clock(now().minute)}</p><label>${t('date')}</label><input type="date" value="${bookingDay}" min="${now().date}" max="${addDays(now().date,db.settings.horizon)}" onchange="bookingDay=this.value;chosen='';render()">${!dayAllowed(bookingDay)?`<p class="error">${t('closed')}</p>`:''}${db.settings.sessions.map((se,i)=>`<h3>${i===0?t('morning'):i===1?t('evening'):i+1} · ${se.start}–${se.end}</h3><div class="slots">${list.filter(s=>s.session===i).map(s=>`<button class="slot ${chosen===String(s.start)?'selected':''}" ${s.ok?'':'disabled'} onclick="chosen='${s.start}';render()"><b>${clock(s.start)}</b><small>${t(s.state)} · ${s.left} ${t('remaining')}</small></button>`).join('')}</div>`).join('')}${!list.some(x=>x.ok)?`<p class="error">${t('noSlots')}</p>`:''}${pick?`<div class="notice">${t('pickup')}: <b>${bookingDay} · ${clock(pick.end)}</b> · Vancouver</div>`:''}<label>${t('notes')}</label><textarea maxlength="200" oninput="notes=this.value;document.getElementById('chars').textContent=this.value.length">${E(notes)}</textarea><small><span id="chars">${notes.length}</span>/200</small><div class="actions"><button onclick="go('home')">${t('back')}</button><button class="primary" ${pick?.ok?'':'disabled'} onclick="go('checkout')">${t('continue')} →</button></div>`}
function summary(items=cart.map((q,i)=>({...db.breads[i],qty:q})),amount=total()){return `${items.filter(i=>i.qty).map(i=>`<p class="row"><span>${E(i[lang])} × ${i.qty}</span><b>${money(i.qty*i.price)}</b></p>`).join('')}<hr><p class="row"><b>${t('total')}</b><strong>${money(amount)}</strong></p>`}
function methods(){return Object.keys(db.settings.payments).filter(k=>db.settings.payments[k]&&(k!=='wallet'||user()))}
function checkoutPage(){let u=user(),pick=slots(bookingDay).find(x=>String(x.start)===chosen),ms=methods();if(!ms.includes(checkout.method))checkout.method=ms[0]||'';return `${progress(3)}<h2>${t('checkout')}</h2><div class="split"><div class="card pad"><div class="notice">${u?E(u.name)+' · '+t('balance')+': '+money(u.balance):t('guest')} <button onclick="go('account')">${t('account')}</button></div><form onsubmit="event.preventDefault();placeOrder()"><label>${t('name')}</label><input id="customerName" required minlength="2" autocomplete="name" value="${E(checkout.name||u?.name||'')}" oninput="checkout.name=this.value"><label>${t('phone')}</label><input id="customerPhone" required type="tel" dir="ltr" value="${E(checkout.phone==='+1'&&u?u.phone:checkout.phone)}" oninput="checkout.phone=this.value"><label>${t('payment')}</label><select onchange="checkout.method=this.value;render()">${ms.map(k=>`<option value="${k}" ${checkout.method===k?'selected':''}>${t(k)}</option>`).join('')}</select><p class="small muted">${t('demo')}</p><div class="actions"><button type="button" onclick="go('schedule')">${t('back')}</button><button class="primary" ${busy||!pick?.ok||!ms.length?'disabled':''}>${t('place')}</button></div></form></div><aside class="card pad"><h3>${t('orders')}</h3>${summary()}<p>${bookingDay} · ${clock(+chosen)}</p><p>${t('pickup')}: <b>${pick?clock(pick.end):'—'}</b></p><p>${t(checkout.method)}</p><p>${E(notes)}</p></aside></div>`}
async function placeOrder(){if(busy)return;const wasWalkin=walkin;let name=document.getElementById('customerName').value.trim(),phone=canadianPhone(document.getElementById('customerPhone').value);checkout.name=name;checkout.phone=phone;if(name.length<2||!canadianPhone(phone))return toast(t('required'));busy=true;render();try{await atomic(()=>{let pick=slots(bookingDay).find(x=>String(x.start)===chosen);if(!pick?.ok||cart.some((q,i)=>q>db.breads[i].max||q&&!db.breads[i].active)||!methods().includes(checkout.method))throw Error(t('capacityError'));let u=walkin?null:user(),amount=total();if(checkout.method==='wallet'&&(!u||u.balance<amount))throw Error(t('insufficient'));let code=codeFor(db.used[bookingDay]||[]),id='BANO-'+db.next++,o={id,date:bookingDay,start:+chosen,end:pick.end,items:cart.map((q,i)=>({...db.breads[i],image:undefined,qty:q})),total:amount,name,phone,userId:u?.id||'',method:checkout.method,payment:checkout.method==='wallet'?'paid':checkout.method==='cash'?'due':'awaiting',status:'pending',code,notes:notes.slice(0,200),source:walkin?'walkin':'online',created:new Date().toISOString()};if(checkout.method==='wallet'){u.balance=dollars(cents(u.balance)-cents(amount));u.transactions.push({at:new Date().toISOString(),amount:-amount,note:id,kind:'wallet_purchase'});financeEvent('wallet_purchase',-cents(amount),{orderId:id,userId:u.id,method:'wallet'})}(db.used[bookingDay]??=[]).push(code);db.orders.push(o);orderId=id});let owned=JSON.parse(BAANOU_STORE.getItem('bano-v2-owned')||'[]');if(!wasWalkin)owned.push(orderId);BAANOU_STORE.setItem('bano-v2-owned',JSON.stringify(owned));cart=[0,0,0];notes='';walkin=false;if(wasWalkin){tab='counterReceipt';go('admin')}else go('confirmation')}catch(e){toast(e.name==='QuotaExceededError'?t('storageError'):e.message);if(wasWalkin){tab='counter';go('admin')}else go('schedule')}finally{busy=false;render()}}
function orderCard(o){return `<div class="card pad"><div class="row"><h3>${o.id}</h3><span class="badge">${t(o.status)}</span></div><p>${o.date} · ${clock(o.start)} → ${t('pickup')} ${clock(o.end)}</p>${summary(o.items,o.total)}<p>${t(o.payment)} · ${t(o.method)}</p><p>${E(o.notes)}</p><label>${t('code')}</label><div class="code" dir="ltr">${o.code}</div><button onclick="copyCode('${o.code}')">${t('copy')}</button>${o.deliveredAt?`<p>${t('delivered')}: ${new Intl.DateTimeFormat(lang==='fa'?'fa-IR':'en-CA',{timeZone:TZ,dateStyle:'short',timeStyle:'short'}).format(new Date(o.deliveredAt))}</p>`:''}</div>`}
function confirmation(){let o=db.orders.find(o=>o.id===orderId);if(!o)return tracking();return `${progress(4)}<div class="center"><div class="eyebrow">✓ BANO BAKERY</div><h2>${t('success')}</h2><p>${t('fresh')}</p></div>${orderCard(o)}<div class="notice"><b>${t('sms')}</b><p>${E(db.settings.name)} · ${o.id} · ${o.date} ${clock(o.end)} · ${t('code')}: ${o.code}</p></div><div class="actions"><button class="primary" onclick="go('track')">${t('track')}</button><button onclick="go('home')">${t('home')}</button></div>`}
async function copyCode(code){try{await navigator.clipboard.writeText(code);toast(t('saved'))}catch{prompt(t('code'),code)}}
function tracking(){let owned=JSON.parse(BAANOU_STORE.getItem('bano-v2-owned')||'[]');return `<h2>${t('myorders')}</h2>${db.orders.filter(o=>owned.includes(o.id)||userId&&o.userId===userId).slice().reverse().map(orderCard).join('<br>')||t('empty')}`}
function accountPage(){let u=user();if(!u)return `<h2>${t('account')}</h2><div class="split"><div class="card pad"><h3>${t('signin')}</h3><p>${t('warning')}</p><select id="demoUser">${db.users.map(u=>`<option value="${u.id}">${E(u.name)} · ${E(u.phone)}</option>`).join('')}</select><div class="actions"><button class="primary" onclick="login(document.getElementById('demoUser').value)">${t('signin')}</button><button onclick="userId='';BAANOU_STORE.removeItem('bano-v2-user');go(chosen&&count()?'checkout':'home')">${t('guest')}</button></div><div class="actions"><button onclick="go('track')">${t('track')}</button></div></div><form class="card pad" onsubmit="event.preventDefault();registerUser(this)"><h3>${t('register')}</h3><label>${t('name')}</label><input name="fullName" required minlength="2"><label>${t('phone')}</label><input name="phone" type="tel" value="+1" required><label>${t('email')}</label><input name="email" type="email"><div class="actions"><button class="primary">${t('register')}</button></div></form></div>`;return `<div class="row"><h2>${E(u.name)}</h2><button onclick="userId='';checkout.name='';checkout.phone='+1';BAANOU_STORE.removeItem('bano-v2-user');render()">${t('logout')}</button></div><div class="split"><section class="card pad"><h3>${t('wallet')}</h3><h2>${money(u.balance)}</h2><button class="primary" onclick="topup()">${t('topup')}</button><h3>${t('transactions')}</h3>${u.transactions.slice().reverse().map(x=>`<p class="row"><span>${E(x.note)}</span><b>${money(x.amount)}</b></p>`).join('')}<p class="small">${t('demo')}</p></section><form class="card pad" onsubmit="event.preventDefault();saveProfile(this)"><h3>${t('personal')}</h3><label>${t('name')}</label><input name="fullName" required minlength="2" value="${E(u.name)}"><label>${t('phone')}</label><input name="phone" required value="${E(u.phone)}"><label>${t('email')}</label><input name="email" type="email" value="${E(u.email)}"><div class="actions"><button>${t('save')}</button><button type="button" onclick="go('checkout')" ${chosen&&count()?'':'disabled'}>${t('checkout')}</button></div></form></div><h2>${t('myorders')}</h2>${db.orders.filter(o=>o.userId===u.id).slice().reverse().map(orderCard).join('<br>')||t('empty')}`}
function login(id){userId=id;checkout.name='';checkout.phone='+1';BAANOU_STORE.setItem('bano-v2-user',id);go(chosen&&count()?'checkout':'account')}
async function registerUser(f){let phone=canadianPhone(f.phone.value);if(!canadianPhone(phone))return toast(t('required'));let id;try{await atomic(()=>{if(db.users.some(u=>u.phone===phone))throw Error(t('usedPhone'));id='u'+crypto.randomUUID();db.users.push({id,name:f.fullName.value.trim(),phone,email:f.email.value,balance:0,transactions:[]})});login(id)}catch(e){toast(e.message)}}
async function topup(){await atomic(()=>{let u=user();u.balance+=25;u.transactions.push({at:new Date().toISOString(),amount:25,note:t('topupNote')})});render()}
async function saveProfile(f){let name=f.fullName.value.trim(),phone=canadianPhone(f.phone.value);if(name.length<2||!canadianPhone(phone))return toast(t('required'));await atomic(()=>Object.assign(user(),{name,phone,email:f.email.value}));render();toast(t('saved'))}
function adminPage(){if(!admin)return `<h2>${t('admin')}</h2><div class="card pad"><p>${t('warning')}</p><button class="primary" onclick="admin=true;render()">${t('enter')}</button></div>`;return `<h2>${t('admin')} · ${E(db.settings.name)}</h2><div class="tabs">${['dashboard','orders','production','handoff','settings','customers'].map(k=>`<button class="${tab===k?'primary':''}" onclick="tab='${k}';verified='';render()">${t(k)}</button>`).join('')}<button onclick="walkin=true;cart=[0,0,0];go('home')">+ ${t('walkin')}</button></div>${tab==='dashboard'?dashboard():tab==='orders'?ordersPage():tab==='production'?production():tab==='handoff'?handoff():tab==='customers'?customers():settingsPage()}`}
function dashboard(){let os=db.orders.filter(o=>o.date===now().date);return `<div class="stats">${[['today',os.length],['pending',os.filter(o=>o.status==='pending').length],['baking',os.filter(o=>o.status==='baking').length],['ready',os.filter(o=>o.status==='ready').length],['delivered',os.filter(o=>o.status==='delivered').length],['revenue',money(os.filter(o=>o.payment==='paid'&&o.status!=='cancelled').reduce((a,o)=>a+o.total,0))]].map(([k,v])=>`<div class="stat">${t(k)}<strong>${v}</strong></div>`).join('')}</div><h3>${t('upcoming')}</h3>${orderTable(os.filter(o=>!['cancelled','delivered'].includes(o.status)).sort((a,b)=>a.start-b.start))}`}
function orderTable(os){return `<div class="tablewrap"><table><thead><tr>${['orderid','name','bread','schedule','payment','code','notes','orders'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${os.map(o=>`<tr><td>${o.id}<br><small>${t(o.source)}</small></td><td>${E(o.name)}<br>${E(o.phone)}</td><td>${o.items.filter(i=>i.qty).map(i=>E(i[lang])+' × '+i.qty).join('<br>')}<br>${money(o.total)}</td><td>${o.date}<br>${clock(o.start)} → ${clock(o.end)}<br><button onclick="delayOrder('${o.id}')">${t('delay')}</button></td><td><span class="${o.payment==='awaiting'?'error':''}">${t(o.payment)}</span><br>${t(o.method)}${o.payment!=='paid'&&!['cancelled'].includes(o.status)?`<br><button onclick="payOrder('${o.id}')">${t('payConfirm')}</button>`:''}</td><td>${o.code}</td><td>${E(o.notes)}</td><td><select onchange="changeStatus('${o.id}',this.value)">${states.map(s=>`<option value="${s}" ${o.status===s?'selected':''} ${s==='delivered'&&o.status!=='delivered'||['cancelled','delivered'].includes(o.status)&&s!==o.status?'disabled':''}>${t(s)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`}
function ordersPage(){return `<p class="small">${t('cancelHint')}</p><div class="row"><input style="max-width:380px" placeholder="${t('search')}" value="${E(search)}" oninput="search=this.value;document.getElementById('rows').innerHTML=filteredOrders()"><select style="max-width:230px" onchange="statusFilter=this.value;render()"><option value="">${t('all')}</option>${states.map(s=>`<option value="${s}" ${statusFilter===s?'selected':''}>${t(s)}</option>`).join('')}</select></div><div id="rows">${filteredOrders()}</div>`}
function filteredOrders(){return orderTable(db.orders.filter(o=>(!statusFilter||o.status===statusFilter)&&[o.id,o.name,o.phone].join(' ').toLowerCase().includes(search.toLowerCase())).slice().reverse())}
async function changeStatus(id,status){try{await atomic(()=>{let o=db.orders.find(o=>o.id===id);if(status==='delivered'||['cancelled','delivered'].includes(o.status))throw Error(t('invalidPickup'));o.status=status;if(status==='cancelled'&&o.method==='wallet'&&o.payment==='paid'&&!o.refunded){let u=db.users.find(u=>u.id===o.userId);u.balance=dollars(cents(u.balance)+cents(o.total));u.transactions.push({at:new Date().toISOString(),amount:o.total,note:o.id+' · '+t('refunded'),kind:'wallet_refund'});financeEvent('wallet_refund',cents(o.total),{orderId:o.id,userId:u.id,method:'wallet'});o.refunded=true;o.payment='refunded'}});render()}catch(e){toast(e.message);render()}}
async function payOrder(id){await atomic(()=>{let o=db.orders.find(o=>o.id===id);if(o.status!=='cancelled')o.payment='paid'});render()}
async function delayOrder(id){let o=db.orders.find(o=>o.id===id),v=prompt(t('pickup')+' · HH:MM (Vancouver)',clock(o.end));if(v===null)return;if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(v)||mins(v)<o.start)return toast(t('invalidSettings'));await atomic(()=>db.orders.find(o=>o.id===id).end=mins(v));render()}
function production(){let date=scheduleDay||now().date,list=slots(date,[0,0,0]);return `<label>${t('date')}</label><input type="date" value="${date}" onchange="scheduleDay=this.value;render()">${db.settings.sessions.map((se,i)=>`<h3>${i===0?t('morning'):i===1?t('evening'):i+1} ${se.start}–${se.end}</h3><div class="slots">${list.filter(s=>s.session===i).map(s=>{let os=db.orders.filter(o=>o.date===date&&o.start===s.start&&o.status!=='cancelled');return `<button class="slot" onclick="document.getElementById('scheduleOrders').innerHTML=orderTable(db.orders.filter(o=>o.date==='${date}'&&o.start===${s.start}))"><b>${clock(s.start)}</b><small>${os.length} ${t('orders')} · ${s.left} ${t('remaining')}</small>${db.breads.map((b,j)=>`<small>${E(b[lang])}: ${os.reduce((a,o)=>a+o.items[j].qty,0)}</small>`).join('')}<small>${os.map(o=>t(o.status)).join(' · ')}</small></button>`}).join('')}</div>`).join('')}<div id="scheduleOrders">${orderTable(db.orders.filter(o=>o.date===date))}</div>`}
function handoff(){return `<div class="card pad"><form onsubmit="event.preventDefault();verifyPickup(this)"><label>${t('orderid')}</label><input name="oid" placeholder="BANO-1042" required><label>${t('code')}</label><input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required><div class="actions"><button class="primary">${t('verify')}</button></div></form>${verified?`<div class="notice">${E(db.orders.find(o=>o.id===verified)?.name)} · ${verified}<br><button class="primary" onclick="confirmPickup()">${t('deliver')}</button></div>`:''}</div><h3>${t('ready')}</h3>${orderTable(db.orders.filter(o=>o.status==='ready'))}`}
function canPickup(id,code){let o=db.orders.find(o=>o.id===id);return !!o&&o.code===code&&o.status==='ready'&&!o.deliveredAt}
function verifyPickup(f){let id=f.oid.value.trim().toUpperCase();if(!canPickup(id,f.code.value)){verified='';toast(t('invalidPickup'));render();return}verified=id;render()}
async function confirmPickup(){try{await atomic(()=>{let o=db.orders.find(o=>o.id===verified);if(!o||!canPickup(o.id,o.code))throw Error(t('invalidPickup'));o.status='delivered';o.deliveredAt=new Date().toISOString()});verified='';render();toast(t('deliveredOk'))}catch(e){verified='';render();toast(e.message)}}
function customers(){return `<div class="tablewrap"><table><tr>${['name','phone','balance','orders','total'].map(k=>`<th>${t(k)}</th>`).join('')}</tr>${db.users.map(u=>{let os=db.orders.filter(o=>o.userId===u.id&&o.status!=='cancelled');return `<tr><td>${E(u.name)}</td><td>${E(u.phone)}</td><td>${money(u.balance)} <button onclick="adjustWallet('${u.id}')">±</button></td><td>${os.length}</td><td>${money(os.reduce((a,o)=>a+o.total,0))}</td></tr>`}).join('')}</table></div>`}
async function adjustWallet(id){let raw=prompt(t('adjust'),'25');if(raw===null)return;let amount=Number(raw);if(!Number.isFinite(amount))return;try{await atomic(()=>{let u=db.users.find(u=>u.id===id);if(u.balance+amount<0)throw Error(t('insufficient'));u.balance+=amount;u.transactions.push({at:new Date().toISOString(),amount,note:t('adjustment')})});render()}catch(e){toast(e.message)}}
function field(name,label,value,type='text',extra=''){return `<label for="${name}">${t(label)}</label><input id="${name}" name="${name}" type="${type}" value="${E(value)}" ${extra}>`}
function check(name,label,value){return `<label><input type="checkbox" name="${name}" ${value?'checked':''}> ${t(label)}</label>`}
let imageDraft={},resetPending=false;
function settingsPage(){let s=db.settings,days=lang==='fa'?['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه']:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];return `<form id="settingsForm" onsubmit="event.preventDefault();saveSettings(this)"><details open><summary>${t('bakery')}</summary>${field('bakeryName','name',s.name,'text','required')}${field('bakeryPhone','phone',s.phone)}${field('address','address',s.address)}${field('storeOpen','storeOpening',s.storeOpen||'08:30','time','required')}${field('storeClose','storeClosing',s.storeClose||'22:00','time','required')}<label>${t('logo')}</label><input type="file" accept="image/*" onchange="loadImage(this,'logo')"><p class="small">${t('currency')}</p></details><details><summary>${t('breadSettings')}</summary>${db.breads.map((b,i)=>`<section class="card pad" style="margin:15px 0"><h3>${E(b[lang])}</h3>${field('en'+i,'nameEn',b.en,'text','required')}${field('fa'+i,'nameFa',b.fa,'text','required')}${field('price'+i,'price',b.price,'number','min="0.01" max="999" step="0.01" required')}${field('bake'+i,'bake',b.bake,'number','min="1" max="240" required')}${field('max'+i,'max',b.max,'number','min="0" max="20" required')}${check('active'+i,'active',b.active)}${field('descriptionEn'+i,'descriptionEn',b.descriptionEn)}${field('descriptionFa'+i,'descriptionFa',b.descriptionFa)}<label>${t('photo')}</label><input type="file" accept="image/*" onchange="loadImage(this,'${i}')"><button type="button" onclick="imageDraft['${i}']='';toast(t('saved'))">${t('remove')}</button></section>`).join('')}</details><details><summary>${t('hours')}</summary><label>${t('weekdays')}</label><div class="row">${days.map((d,i)=>`<label><input type="checkbox" name="day${i}" ${s.days.includes(i)?'checked':''}> ${d}</label>`).join('')}</div>${field('holidays','holidays',s.holidays.join(','))}<label>${t('sessions')}</label><textarea name="sessions" rows="4" required>${s.sessions.map(se=>se.start+'-'+se.end).join('\n')}</textarea>${field('interval','interval',s.interval,'number','min="5" max="240" required')}${field('horizon','horizon',s.horizon,'number','min="1" max="365" required')}</details><details><summary>${t('capacity')}</summary>${['ovens','ovenCapacity','slotCapacity','maxOrders','packing'].map(k=>field(k,k,s[k],'number',`min="${k==='packing'?0:1}" max="${k==='ovens'?20:500}" required`)).join('')}${check('overrun','overrun',s.overrun)}<label>${t('overrides')}</label><p class="small">${t('overrideHelp')}</p><textarea name="overrides" rows="4">${Object.entries(s.overrides).map(([k,v])=>`${k},${v.capacity},${v.disabled?1:0}`).join('\n')}</textarea></details><details><summary>${t('payment')}</summary>${['cash','transfer','wallet'].map(k=>check(k,k,s.payments[k])).join('')}</details><div class="actions"><button class="primary">${t('save')}</button><button type="button" onclick="resetDemo()">${t('reset')}</button></div></form>${resetPending?`<div class="notice">${t('resetAsk')}<div class="actions"><button type="button" class="primary" onclick="resetDemo(true)">${t('reset')}</button><button type="button" onclick="resetPending=false;render()">${t('back')}</button></div></div>`:''}<p class="small muted">${t('cancelHint')}</p>`}
function loadImage(input,key){let file=input.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>700000){input.value='';return toast(t('imageError'))}let reader=new FileReader();reader.onload=()=>{imageDraft[key]=reader.result;toast(t('saved'))};reader.readAsDataURL(file)}
function validSettings(s,breads,orders=db.orders){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(s.storeOpen||'08:30')||!/^([01]\d|2[0-3]):[0-5]\d$/.test(s.storeClose||'22:00')||mins(s.storeOpen||'08:30')>=mins(s.storeClose||'22:00'))return false;if(!s.name.trim()||!s.days.length||!s.sessions.length||!Object.values(s.payments).some(Boolean)||s.interval<5||s.interval>240||s.horizon<1||s.horizon>365||s.ovens<1||s.ovens>20||s.ovenCapacity<1||s.slotCapacity<1||s.maxOrders<1||s.packing<0)return false;
let previous=-1;for(let se of s.sessions){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(se.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(se.end)||mins(se.start)>=mins(se.end)||mins(se.start)<previous)return false;previous=mins(se.end)}
if(breads.some(b=>!b.en.trim()||!b.fa.trim()||!Number.isFinite(b.price)||b.price<=0||b.bake<1||b.bake>240||b.max<0||b.max>20))return false;
for(let [key,v] of Object.entries(s.overrides))if(!/^\d{4}-\d{2}-\d{2}@([01]\d|2[0-3]):[0-5]\d$/.test(key)||!Number.isInteger(v.capacity)||v.capacity<0)return false;
if(s.holidays.some(d=>!/^\d{4}-\d{2}-\d{2}$/.test(d)))return false;
let n=now();for(let o of orders.filter(o=>!['cancelled','delivered'].includes(o.status)&&(o.date>n.date||o.date===n.date&&o.start>n.minute))){let se=s.sessions.find(se=>o.start>=mins(se.start)&&o.start<mins(se.end)&&(o.start-mins(se.start))%s.interval===0),ov=s.overrides[o.date+'@'+clock(o.start)]||{},same=orders.filter(x=>x.date===o.date&&x.start===o.start&&x.status!=='cancelled'),bakeEnd=o.start+Math.max(...o.items.filter(i=>i.qty).map(i=>i.bake));if(o.end>mins(s.storeClose||'22:00')||o.end<mins(s.storeOpen||'08:30'))return false;if(!se||!s.days.includes(new Date(o.date+'T12:00:00Z').getUTCDay())||s.holidays.includes(o.date)||ov.disabled||!s.overrun&&bakeEnd+s.packing>mins(se.end)||same.length>s.maxOrders||same.reduce((a,x)=>a+x.items.reduce((a,i)=>a+i.qty,0),0)>(ov.capacity??s.slotCapacity)||usedAt(o.date,o.start,bakeEnd,orders)>s.ovens*s.ovenCapacity)return false}return true}
