const oldSeed=seed;seed=function(){let s=oldSeed();s.settings.name='Baanou Bakert';if(db?.auth)s.auth=structuredClone(db.auth);s.brandVersion=3;return s};
function sessionAccount(){return db.auth?.find(a=>a.id===identity?.id&&a.version===identity.version)}
function isManager(){return sessionAccount()?.role==='admin'}
function isOperator(){return ['admin','staff'].includes(sessionAccount()?.role)}
function credentialName(s){return String(s||'').trim().toLowerCase()}
function usernameValid(s){return /^[a-zA-Z0-9_.-]{3,32}$/.test(s)}
async function passwordRecord(password,salt){salt=salt||Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');let key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);let bytes=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},key,256);return {salt,hash:Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join(''),iterations:120000}}
async function passwordMatches(password,record){if(!record?.salt||!record?.hash)return false;let result=await passwordRecord(password,record.salt);return result.hash===record.hash}
function authInput(name,key,type='text',extra=''){return `<label for="${name}">${t(key)}</label><input id="${name}" name="${name}" type="${type}" required ${extra}>`}
function signInPage(){return `<div class="auth-intro"><span class="eyebrow">BAANOU BAKERT</span><h2>${t('signIn')}</h2><p class="muted">${t('loginHelp')}</p></div><div class="split auth-layout"><section class="card pad"><form onsubmit="event.preventDefault();signIn(this)">${authInput('loginUsername','username','text','autocomplete="username" autocapitalize="none" spellcheck="false"')}${authInput('loginPassword','password','password','autocomplete="current-password"')}<button class="primary wide" style="margin-top:24px" ${!authReady||authBusy?'disabled':''}>${authReady?t('signIn'):t('authLoading')}</button></form><p class="small muted">${t('credentials')}</p><p class="small muted">${t('customerDemo')}</p><button class="wide" onclick="signOut(true)">${t('guest')}</button><p class="small muted">${t('authDemo')}</p></section><form class="card pad" onsubmit="event.preventDefault();registerUser(this)"><h3>${t('register')}</h3>${authInput('fullName','name','text','minlength="2" autocomplete="name"')}${authInput('phone','phone','tel','value="+1" autocomplete="tel"')}<label>${t('email')}</label><input name="email" type="email" autocomplete="email">${authInput('newUsername','username','text','minlength="3" maxlength="32" autocomplete="username" autocapitalize="none" spellcheck="false"')}${authInput('newCustomerPassword','password','password','minlength="10" autocomplete="new-password"')}<button class="wide" style="margin-top:24px" ${!authReady||authBusy?'disabled':''}>${t('register')}</button></form></div>`}
function signOut(guest=false){identity=null;userId='';admin=false;walkin=false;verified='';checkout.name='';checkout.phone='+1';BAANOU_STORE.removeItem('bano-v2-user');go(guest?'home':'account')}
async function signIn(f){if(authBusy||!authReady)return;let username=credentialName(f.loginUsername.value),password=f.loginPassword.value;authBusy=true;try{read();let a=db.auth.find(a=>credentialName(a.username)===username);if(!a||!await passwordMatches(password,a.password))throw Error(t('loginFail'));read();let current=db.auth.find(x=>x.id===a.id&&x.version===a.version);if(!current)throw Error(t('loginFail'));identity={id:current.id,version:current.version};userId=current.role==='customer'?current.userId:'';admin=isOperator();checkout.name='';checkout.phone='+1';if(isOperator()){tab='dashboard';go('admin')}else go(count()&&chosen?'checkout':'account')}catch(e){toast(e.message)}finally{authBusy=false;render()}}
login=function(){go('account')}; // Remove the old demo user-selector bypass.
registerUser=async function(f){if(authBusy||!authReady)return;let name=f.fullName.value.trim(),phone=canadianPhone(f.phone.value),email=f.email.value,username=f.newUsername.value.trim(),password=f.newCustomerPassword.value;if(name.length<2||!canadianPhone(phone))return toast(t('required'));if(!usernameValid(username))return toast(t('badUsername'));if(password.length<10)return toast(t('badPassword'));authBusy=true;try{let record=await passwordRecord(password),account;await atomic(()=>{if(db.auth.some(a=>credentialName(a.username)===credentialName(username)))throw Error(t('badUsername'));if(db.users.some(u=>u.phone===phone))throw Error(t('usedPhone'));let id='u'+crypto.randomUUID();db.users.push({id,name,phone,email,balance:0,transactions:[]});account={id:crypto.randomUUID(),username,role:'customer',userId:id,version:1,password:record};db.auth.push(account)});identity={id:account.id,version:1};userId=account.userId;admin=false;go(count()&&chosen?'checkout':'account')}catch(e){toast(e.message)}finally{authBusy=false;render()}};
const accountV2=accountPage;accountPage=function(){let a=sessionAccount();if(!a)return signInPage();if(a.role!=='customer')return adminPage();return `<div class="small muted">${t('signedInAs')}: ${E(a.username)} · ${t('customerRole')}</div>`+accountV2().replace(/<button onclick="userId='';[^"]*">.*?<\/button>/g,'')+ownPasswordForm()};
function ownPasswordForm(){return `<form class="card pad password-form" onsubmit="event.preventDefault();changeMyPassword(this)"><h3>${t('changePassword')}</h3>${authInput('currentPassword','currentPassword','password','autocomplete="current-password"')}${authInput('newPassword','newPassword','password','minlength="10" autocomplete="new-password"')}${authInput('repeatPassword','repeatPassword','password','minlength="10" autocomplete="new-password"')}<div class="actions"><button class="primary" ${authBusy?'disabled':''}>${t('changePassword')}</button></div></form>`}
async function changeMyPassword(f){let a=sessionAccount();if(!a)return toast(t('forbidden'));let old=f.currentPassword.value,next=f.newPassword.value,repeat=f.repeatPassword.value;if(next.length<10||next!==repeat)return toast(t('badPassword'));if(authBusy)return;authBusy=true;try{if(!await passwordMatches(old,a.password))throw Error(t('loginFail'));let record=await passwordRecord(next);await atomic(()=>{let current=sessionAccount();if(!current)throw Error(t('forbidden'));current.password=record;current.version++;identity.version=current.version});render();toast(t('passwordChanged'))}catch(e){toast(e.message)}finally{authBusy=false;render()}}
function securityPage(){let a=sessionAccount();if(!a)return signInPage();let staff=db.auth.filter(a=>a.role==='staff');return `<p class="muted">${t('signedInAs')}: <b>${E(a.username)}</b> · ${t(a.role==='admin'?'adminRole':'staffRole')}</p>${ownPasswordForm()}${isManager()?`<section class="card pad staff-panel"><h3>${t('staff')}</h3><p class="small muted">${t('staffScope')}</p><p class="small">${staff.length} / 2</p>${staff.map(a=>`<div class="staff-row"><strong>${E(a.username)}</strong><form onsubmit="event.preventDefault();setStaffPassword('${a.id}',this)"><label>${t('newPassword')}</label><input name="staffPassword" type="password" minlength="10" required autocomplete="new-password"><button ${authBusy?'disabled':''}>${t('changeStaffPassword')}</button></form><button onclick="staffRemoval='${a.id}';render()">${t('removeStaff')}</button>${staffRemoval===a.id?`<div class="notice">${t('removeAsk')}<button onclick="removeStaff('${a.id}')">${t('removeStaff')}</button><button onclick="staffRemoval='';render()">${t('back')}</button></div>`:''}</div>`).join('')}${staff.length<2?`<form onsubmit="event.preventDefault();createStaff(this)"><h3>${t('createStaff')}</h3>${authInput('staffUsername','username','text','minlength="3" maxlength="32" autocomplete="off" autocapitalize="none"')}${authInput('staffPassword','password','password','minlength="10" autocomplete="new-password"')}<div class="actions"><button class="primary" ${authBusy?'disabled':''}>${t('createStaff')}</button></div></form>`:`<div class="notice">${t('staffLimit')}</div>`}</section>`:''}<p class="small muted">${t('authDemo')}</p>`}
async function createStaff(f){if(!isManager())return toast(t('forbidden'));if(authBusy)return;let username=f.staffUsername.value.trim(),password=f.staffPassword.value;if(!usernameValid(username))return toast(t('badUsername'));if(password.length<10)return toast(t('badPassword'));authBusy=true;try{let record=await passwordRecord(password);await atomic(()=>{if(!isManager())throw Error(t('forbidden'));if(db.auth.filter(a=>a.role==='staff').length>=2)throw Error(t('staffLimit'));if(db.auth.some(a=>credentialName(a.username)===credentialName(username)))throw Error(t('badUsername'));db.auth.push({id:crypto.randomUUID(),username,role:'staff',version:1,password:record})});toast(t('staffCreated'))}catch(e){toast(e.message)}finally{authBusy=false;render()}}
async function setStaffPassword(id,f){if(!isManager()||authBusy)return toast(t('forbidden'));let password=f.staffPassword.value;if(password.length<10)return toast(t('badPassword'));authBusy=true;try{let record=await passwordRecord(password);await atomic(()=>{if(!isManager())throw Error(t('forbidden'));let a=db.auth.find(a=>a.id===id&&a.role==='staff');if(!a)throw Error(t('forbidden'));a.password=record;a.version++});toast(t('passwordChanged'))}catch(e){toast(e.message)}finally{authBusy=false;render()}}
async function removeStaff(id){try{await atomic(()=>{if(!isManager())throw Error(t('forbidden'));db.auth=db.auth.filter(a=>a.id!==id||a.role!=='staff')});staffRemoval='';render();toast(t('staffRemoved'))}catch(e){toast(e.message)}}
const adminV2=adminPage;adminPage=function(){if(!isOperator())return signInPage();admin=true;let allowed=isManager()?['dashboard','orders','production','handoff','settings','customers','security','counter','counterReceipt']:['dashboard','orders','production','handoff','security','counter','counterReceipt'];if(!allowed.includes(tab))tab='dashboard';if(tab==='security')return `<div class="pagehead row"><h2>${t('security')}</h2><button onclick="tab='dashboard';render()">${t('backQueue')}</button></div>`+securityPage();let html=adminV2();if(!isManager())html=html.replace(/<button[^>]*onclick="tab='(?:settings|customers)'[^>]*>.*?<\/button>/g,'');return html};
// Explicit role gates also cover direct calls to the old local handlers.
function guard(fn,managerOnly=false){return function(...args){if(!(managerOnly?isManager():isOperator())){toast(t('forbidden'));return}return fn(...args)}}
enterCounter=guard(enterCounter);changeStatus=guard(changeStatus);payOrder=guard(payOrder);delayOrder=guard(delayOrder);verifyPickup=guard(verifyPickup);confirmPickup=guard(confirmPickup);saveSettings=guard(saveSettings,true);adjustWallet=guard(adjustWallet,true);resetDemo=guard(resetDemo,true);
const orderV2=placeOrder;placeOrder=function(){if(walkin&&!isOperator())return toast(t('forbidden'));return orderV2()};
const renderAuthBase=render;render=function(){if(!sessionAccount()){identity=null;userId='';admin=false;if(view==='admin')view='account'}else if(!isOperator()&&view==='admin')view='account';renderAuthBase();let nav=document.getElementById('nav');nav.innerHTML=`<button onclick="go('home')">${t('home')}</button><button onclick="go('${isOperator()?'admin':'account'}')">${sessionAccount()?t(isOperator()?'queue':'account'):t('signIn')}</button>${isOperator()?`<button onclick="tab='security';go('admin')">${t('security')}</button>`:''}${sessionAccount()?`<button onclick="signOut()">${t('logout')}</button>`:''}<button onclick="toggleLang()">${lang==='en'?'فارسی':'EN'}</button><button aria-label="${t('bread')}" onclick="go('home')">◌ ${count()}</button>`;document.querySelectorAll('label').forEach((l,i)=>{let c=l.nextElementSibling;if(!l.htmlFor&&c?.matches('input,select,textarea')){c.id=c.id||'authfield-'+i;l.htmlFor=c.id}})};
