function toggleMobileMenu(){mobileMenuOpen=!mobileMenuOpen;let e=document.getElementById('mobileMenu'),b=document.getElementById('mobileMenuToggle');if(e)e.hidden=!mobileMenuOpen;if(b){b.setAttribute('aria-expanded',String(mobileMenuOpen));b.setAttribute('aria-label',t(mobileMenuOpen?'closeMenu':'menu'))}}
function menuGo(v,section){mobileMenuOpen=false;if(section)tab=section;go(v)}
