const signInV3=signInPage;signInPage=function(){let s=signInV3();return s.replace('<form class="card pad" onsubmit="event.preventDefault();registerUser(this)">','<details class="register-disclosure"><summary>'+t('createAccountAction')+'</summary><form class="card pad" onsubmit="event.preventDefault();registerUser(this)">').replace('</form></div>','</form></details></div>')};
// A shared table structure remains accessible on desktop and becomes labeled cards on phones.
const orderTableV3=orderTable;orderTable=function(os){let i=0,labels=['orderid','name','bread','schedule','payment','code','notes','orders'];return orderTableV3(os).replace(/<td>/g,()=>`<td data-label="${E(t(labels[i++%labels.length]))}">`)};
const checkoutV3=checkoutPage;checkoutPage=function(){return checkoutV3().replace('class="split"','class="split checkout-layout"')};
