if(innerWidth<=700){let n=document.getElementById('nav');n.innerHTML=`<button class="language-toggle" onclick="toggleLang()" aria-label="${lang==='fa'?'English':'فارسی'}">${lang==='en'?'فا':'EN'}</button><button id="mobileMenuToggle" aria-controls="mobileMenu" aria-expanded="false" aria-label="${t('menu')}" onclick="toggleMobileMenu()">☰</button><div class="mobile-menu" id="mobileMenu" hidden><button onclick="menuGo('home')">${t('home')}</button><button onclick="menuGo('${isOperator()?'admin':'account'}')">${sessionAccount()?t(isOperator()?'queue':'account'):t('signIn')}</button>${isOperator()?`<button onclick="menuGo('admin','security')">${t('security')}</button>`:''}${sessionAccount()?`<button onclick="mobileMenuOpen=false;signOut()">${t('logout')}</button>`:''}</div>`;mobileMenuOpen=false}
document.querySelectorAll('.tablewrap table').forEach(table=>{let heads=[...table.querySelectorAll('tr:first-child th')].map(th=>th.textContent);table.querySelectorAll('tr').forEach(tr=>tr.querySelectorAll('td').forEach((td,i)=>{if(!td.dataset.label)td.dataset.label=heads[i]||''}))});
